/**
 * frontend/src/api_service.js - VERSION FINALE CORRIGÉE
 * ✔ Enroll → UploadFile (FormData) vers /students/enroll_from_image/
 * ✔ Recognition → Base64 (rapide pour caméra)
 * ✔ Interceptors JWT
 */

import axios from "axios";

const API_BASE_URL = "http://localhost:8000";

/**
 * ============ AXIOS INSTANCE ============
 */
const api = axios.create({
  baseURL: API_BASE_URL,
  timeout: 20000,
});

/**
 * ============ UTILS ============
 */
const cleanBase64 = (base64String) => {
  if (!base64String) return "";
  if (base64String.startsWith("data:")) {
    return base64String.split(",")[1];
  }
  return base64String;
};

/**
 * ============ INTERCEPTORS ============
 */
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem("access_token");
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }

    console.log(`📤 [${config.method?.toUpperCase()}] ${config.url}`);
    return config;
  },
  (error) => Promise.reject(error)
);

api.interceptors.response.use(
  (response) => {
    console.log(`✅ [${response.status}] ${response.config.url}`);
    return response;
  },
  (error) => {
    const status = error.response?.status;

    if (status === 401) {
      localStorage.clear();
      window.location.href = "/";
    }

    console.error("❌ API Error:", error.response?.data || error.message);
    return Promise.reject(error);
  }
);

/**
 * ============ STUDENTS API ============
 */
export const studentsAPI = {
  getAll: () => api.get("/students/"),

  getOne: (studentId) => api.get(`/students/${studentId}/`),

  create: (data) => api.post("/students/", data),

  /**
   * ✅ ENROLL (VERSION FINALE CORRIGÉE)
   * Upload direct fichier vers Django REST
   */
  enrollFromImage: (name, email, file) => {
    const formData = new FormData();
    formData.append("name", name);
    formData.append("email", email || "");
    formData.append("file", file);

    return axios.post(`${API_BASE_URL}/students/enroll_from_image/`, formData, {
      headers: {
        "Content-Type": "multipart/form-data",
      },
    });
  },

  search: (query) => api.post("/students/search/", { query }),

  getStats: () => api.get("/students/stats/"),

  update: (studentId, data) => api.put(`/students/${studentId}/`, data),

  delete: (studentId) => api.delete(`/students/${studentId}/`),
};

/**
 * ============ ATTENDANCE API ============
 */
export const attendanceAPI = {
  getTodayLog: () => api.get("/attendance/"),

  /**
   * ✅ RECOGNITION (caméra → base64 léger)
   */
  recognize: (imageBase64) => {
    return api.post("/attendance/recognize/", {
      image_base64: cleanBase64(imageBase64),
    });
  },

  /**
   * ⚙️ DEBUG ONLY
   */
  extractEmbedding: (imageBase64) => {
    return api.post("/attendance/extract_embedding/", {
      image_base64: cleanBase64(imageBase64),
    });
  },

  getStats: () => api.get("/attendance/stats/"),

  getStatus: () => api.get("/attendance/status/"),

  getHistory: (studentId, days = 30) => {
    return api.get("/attendance/student_history/", {
      params: { student_id: studentId, days },
    });
  },
};

/**
 * ============ AUTH UTILS ============
 */
export const setAuthToken = (token) => {
  if (token) {
    api.defaults.headers.common["Authorization"] = `Bearer ${token}`;
  }
};

export const clearAuthToken = () => {
  delete api.defaults.headers.common["Authorization"];
  localStorage.removeItem("access_token");
};

export default api;
